const {
  withPlugins,
  withPodfile,
  withProjectBuildGradle,
  withXcodeProject,
} = require('expo/config-plugins')

/**
 * Native build fixes needed after the Expo SDK 58 / library upgrade.
 * None of these change runtime behaviour; they only make the native
 * projects generated by `expo prebuild` compile.
 */

// ---------------------------------------------------------------------------
// iOS: react-native-date-picker header search paths
// ---------------------------------------------------------------------------
// react-native-date-picker imports React headers with quotes
// (e.g. `#import "RCTComponent.h"`). With `useFrameworks: 'dynamic'`
// (required by @react-native-firebase v27 / Firebase Apple SDK 13 SPM) and
// Expo's prebuilt React core, those headers live inside React.framework and
// are not on the pod's header search path, so the iOS build fails with
// "'RCTComponent.h' file not found".
const IOS_TAG = '# caretracker: date-picker header search paths'
const IOS_RUBY = `    ${IOS_TAG}
    installer.pods_project.targets.each do |target|
      next unless target.name == 'react-native-date-picker'
      target.build_configurations.each do |build_config|
        paths = build_config.build_settings['HEADER_SEARCH_PATHS'] || ['$(inherited)']
        paths = [paths] if paths.is_a?(String)
        paths << '"$(PODS_XCFRAMEWORKS_BUILD_DIR)/React-Core-prebuilt/React.framework/Headers"'
        build_config.build_settings['HEADER_SEARCH_PATHS'] = paths
      end
    end
`

const withDatePickerHeaderSearchPaths = (config) =>
  withPodfile(config, (cfg) => {
    const podfile = cfg.modResults.contents
    if (!podfile.includes(IOS_TAG)) {
      cfg.modResults.contents = podfile.replace(
        /post_install do \|installer\|\n/,
        (match) => match + IOS_RUBY
      )
    }
    return cfg
  })

// ---------------------------------------------------------------------------
// Android: react-native-branch BuildConfig
// ---------------------------------------------------------------------------
// react-native-branch 7.0.0 declares a `buildConfigField` but does not enable
// `buildFeatures.buildConfig`. Android Gradle Plugin 9 (React Native 0.88)
// disables BuildConfig by default, so configuring the module fails with
// "defaultConfig contains custom BuildConfig fields, but the feature is
// disabled". Enable it for that module only.
const ANDROID_TAG = '// caretracker: react-native-branch buildConfig'
const ANDROID_GRADLE = `
${ANDROID_TAG}
subprojects { subproject ->
  if (subproject.name == 'react-native-branch') {
    subproject.plugins.withId('com.android.library') {
      subproject.android.buildFeatures.buildConfig = true
    }
  }
}
`

const withBranchBuildConfig = (config) =>
  withProjectBuildGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(ANDROID_TAG)) {
      cfg.modResults.contents += ANDROID_GRADLE
    }
    return cfg
  })

// ---------------------------------------------------------------------------
// iOS: Sentry "Upload Debug Symbols to Sentry" build phase
// ---------------------------------------------------------------------------
// The phase added by @sentry/react-native runs `${NODE_BINARY:-node}` without
// sourcing ios/.xcode.env(.local) first. When archiving from the Xcode GUI with
// node installed via nvm, `node` isn't on PATH and the archive fails with
// "node: command not found". Source the same env files the "Bundle React
// Native code and images" phase uses so NODE_BINARY is set.
const SENTRY_PHASE = 'Upload Debug Symbols to Sentry'
const XCODE_ENV_SOURCE = [
  'if [ -f "$SRCROOT/.xcode.env" ]; then . "$SRCROOT/.xcode.env"; fi',
  'if [ -f "$SRCROOT/.xcode.env.local" ]; then . "$SRCROOT/.xcode.env.local"; fi',
  '',
].join('\n')

const decodeShellScript = (value) => {
  try {
    return JSON.parse(value)
  } catch {
    // Not JSON-encoded yet (freshly created phase): strip the outer quotes
    return value.replace(/^"/, '').replace(/"$/, '').replace(/\\"/g, '"')
  }
}

const withSentryPhaseNodeBinary = (config) =>
  withXcodeProject(config, (cfg) => {
    const phases =
      cfg.modResults.hash.project.objects.PBXShellScriptBuildPhase || {}
    for (const phase of Object.values(phases)) {
      if (typeof phase !== 'object' || !phase.shellScript) continue
      if (!String(phase.name || '').includes(SENTRY_PHASE)) continue
      const script = decodeShellScript(phase.shellScript)
      if (script.includes('.xcode.env')) continue
      phase.shellScript = JSON.stringify(XCODE_ENV_SOURCE + script)
    }
    return cfg
  })

module.exports = function withNativeBuildFixes(config) {
  return withPlugins(config, [
    withDatePickerHeaderSearchPaths,
    withBranchBuildConfig,
    withSentryPhaseNodeBinary,
  ])
}
